import{_ as a,o,c as e,a4 as n}from"./chunks/framework.B0hSrcZ6.js";const s="/info/09-group-team.webp",l="/info/09-group-team-s1.webp",r="/info/09-group-team-s4.webp",i="/info/09-group-team-s5.webp",k=JSON.parse('{"title":"第 9 章 群聊与团队 Bot：从一个 Bot 到一组 Bot","description":"本章介绍多智能体协同与幕僚长多 Bot 分工，详解 Grok Bot 单入口派活模式与共享文件交接，把控外部通信路由，防止多个角色互相唤醒耗尽整周额度。","frontmatter":{},"headers":[],"relativePath":"part1/09-group-team.md","filePath":"part1/09-group-team.md","lastUpdated":1792415157000}'),p={name:"part1/09-group-team.md"};function d(h,t,c,g,b,u){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="第-9-章-群聊与团队-bot-从一个-bot-到一组-bot" tabindex="-1">第 9 章 群聊与团队 Bot：从一个 Bot 到一组 Bot <a class="header-anchor" href="#第-9-章-群聊与团队-bot-从一个-bot-到一组-bot" aria-label="Permalink to &quot;第 9 章 群聊与团队 Bot：从一个 Bot 到一组 Bot&quot;">​</a></h1><p>别把活全塞给一个 Bot，也<strong>别拉多个 Bot 进群</strong>。多 Bot 容易互相接话、循环唤醒并耗尽整周额度，个人 Bot 进 Slack 也无法协同。</p><ol><li>用<strong>统筹 Bot 作单一入口</strong>，靠本地与云电脑共享文件交接任务。</li><li>需要全员共享经验时，发布团队 Bot。</li><li>依 2026-10-12 生效的 The X Subscription 统一订阅机制控好用量。</li></ol><p><img src="'+s+'" alt="群聊与团队 Bot：从一个 Bot 到一组 Bot" width="1600" height="1013" decoding="async"></p><h2 id="群聊机制与交互规则-多-bot-如何在同一对话中协作" tabindex="-1">群聊机制与交互规则：多 Bot 如何在同一对话中协作 <a class="header-anchor" href="#群聊机制与交互规则-多-bot-如何在同一对话中协作" aria-label="Permalink to &quot;群聊机制与交互规则：多 Bot 如何在同一对话中协作&quot;">​</a></h2><p><img src="'+l+'" alt="群聊机制与交互规则：多 Bot 如何在同一对话中协作" width="1600" height="1013" loading="lazy" decoding="async"></p><p>群聊可拉多 Bot，但<strong>团队 Bot 无法与本地 Bot 放同一群</strong>。</p><p>发消息默认全员回，指定用 <code>@Bot名称</code>。复杂任务中 Bot 的私聊交接不同步到群里。</p><p>怕私聊太散，直接立规矩：</p><ul><li><strong>临时约束</strong>：群里发指令。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>就在群里回复，这件事不要私信我。</span></span></code></pre></div><ul><li><strong>长期约束</strong>：让它记入长期记忆。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记住：在群组聊天中，要在群里回复。</span></span></code></pre></div><p>系统没有一键禁互聊开关，防连环调用浪费额度有这几招：</p><ol><li><strong>临时禁令</strong>：群里发指令。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不要给其他 Bot 发消息，先问我。</span></span></code></pre></div><ol start="2"><li><strong>长期规则</strong>：要求未经确认严禁私下唤醒其他 Bot。</li><li><strong>紧急叫停</strong>：停不下来时，<strong>进它的专属私聊叫停</strong>。</li><li><strong>辅助静音</strong>：关通知，或侧边栏右键 Hide from sidebar。</li></ol><p>管理与限制：</p><ul><li><strong>改名与换方向</strong>：右键 Rename chat（手机端点群名 Edit name）；换方向直接群里说明。</li><li><strong>功能限制</strong>：<strong>群聊完全不支持语音</strong>（只能单聊），无法对单个 Bot 开关通知。</li></ul><p>验收标准：</p><ul><li>成员在 3 个以内，职责无重叠。</li><li>提问用 <code>@</code> 精确唤起。</li><li>输出集中在群内，无多余私聊。</li><li>未出现 Bot 间连环唤醒。</li></ul><h2 id="bot-间通信与-slack-权限路由" tabindex="-1">Bot 间通信与 Slack 权限路由 <a class="header-anchor" href="#bot-间通信与-slack-权限路由" aria-label="Permalink to &quot;Bot 间通信与 Slack 权限路由&quot;">​</a></h2><p><strong>Bot 只有在代表具体某个人时，才能跨机器人发消息。</strong> 个人 Bot 在公开 Thread 里没有代表权，无法唤醒其他 Bot；团队 Bot 在被 @ 时承接提问者身份，把任务转交给他自己的专属 Bot，再把结果发回同个 Thread。</p><table tabindex="0"><thead><tr><th>Bot 类型</th><th>提问位置</th><th>跨 Bot 权限</th><th>代表谁</th><th>回复位置</th></tr></thead><tbody><tr><td>个人 Bot</td><td>应用内私聊 / Slack 私信</td><td>能发</td><td>个人</td><td>应用内聊天窗口（非 Slack）</td></tr><tr><td>个人 Bot</td><td>Slack 公开 Thread</td><td>不能发（提示无法执行）</td><td>无人</td><td>原消息串</td></tr><tr><td>团队 Bot</td><td>Slack 频道 / 私信</td><td>能发（转给提问者专属 Bot）</td><td>提问成员</td><td>发回同个 Slack 消息串</td></tr></tbody></table><p><a href="https://cursor.com/cn/help/grok-bot/group-chats" target="_blank" rel="noreferrer">详细规则可见官方文档</a>。</p><h3 id="团队-bot-接入与排坑" tabindex="-1">团队 Bot 接入与排坑 <a class="header-anchor" href="#团队-bot-接入与排坑" aria-label="Permalink to &quot;团队 Bot 接入与排坑&quot;">​</a></h3><ol><li>团队 Bot 发布后，所有者点击聊天顶部 Bot 名称，在 Bring to your team&#39;s Slack 点击 Connect（未发布时显示灰色的 Connect after publishing）。</li><li>界面若提示 Awaiting admin approval，说明开启了安全管控，联系管理员审批；状态变为 Connected 即绑定成功。</li><li><strong>团队成员使用前须在客户端 Settings &gt; General &gt; Team Bots 点击 Link 绑定账号。</strong> 未关联就直接在 Slack 发消息，Bot 只会回复绑定提示。</li></ol><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>Slack 频道内的多 Bot 协作由团队 Bot 统一调度。</li><li>团队成员完成账号 Link。</li><li><strong>任务在 Thread 内部闭环，没有脱节或权限报错。</strong></li></ul><h2 id="团队-bot-全流程配置-创建、发布与跨人共享" tabindex="-1">团队 Bot 全流程配置：创建、发布与跨人共享 <a class="header-anchor" href="#团队-bot-全流程配置-创建、发布与跨人共享" aria-label="Permalink to &quot;团队 Bot 全流程配置：创建、发布与跨人共享&quot;">​</a></h2><p>团队 Bot 由成员创建并全员共享，私聊相互隔离。<strong>它只在云端运行，不能绑在本地</strong>。<a href="https://cursor.com/cn/help/grok-bot/team-bots" target="_blank" rel="noreferrer">参考官方指南</a>。</p><h3 id="创建与转为团队-bot" tabindex="-1">创建与转为团队 Bot <a class="header-anchor" href="#创建与转为团队-bot" aria-label="Permalink to &quot;创建与转为团队 Bot&quot;">​</a></h3><ol><li>侧边栏点 New chat（+），选 Create new Team Bot。</li><li>交代需求，配置公开插件、Secrets 与文件。</li><li>改名并填写 About。<strong>若保留默认名且描述为空，其他成员在列表里搜不到该 Bot</strong>。</li><li>点击卡片上的 Publish to Team。</li></ol><p>已有个人 Bot 可在界面点 Share &gt; 发布到团队克隆独立副本，生成 Slack 账号，按需迁移机密、记忆与例程（Routines）。</p><h3 id="查找与调用" tabindex="-1">查找与调用 <a class="header-anchor" href="#查找与调用" aria-label="Permalink to &quot;查找与调用&quot;">​</a></h3><ul><li><strong>搜索与列表</strong>：在 New chat（+）选团队 Bot 浏览，或在搜索框输入名称前 3 个字符。</li><li><strong>链接直达</strong>：右键选 Copy link。全员共用底座与记忆，非克隆模板。</li><li><strong>批量派发</strong>：管理员在仪表盘 Manage Team Bots 勾选 Auto-add。<strong>被勾选成员侧边栏自动置顶且无法隐藏</strong>。</li></ul><h3 id="权限与运行机制" tabindex="-1">权限与运行机制 <a class="header-anchor" href="#权限与运行机制" aria-label="Permalink to &quot;权限与运行机制&quot;">​</a></h3><p>调用个人账户时触发 Allow 授权（Allow once 仅本次，Always allow 始终允许，Skip 跳过）。重置进 Settings &gt; General &gt; Team Bots 点 Clear。</p><p><strong>审批卡片只在所有者私聊弹出</strong>。群聊与 Slack 中 Bot 只能自主运行。</p><table tabindex="0"><thead><tr><th>场景</th><th>运行环境</th></tr></thead><tbody><tr><td>私聊</td><td>默认个人云电脑（隐私严则分隔离机）</td></tr><tr><td>Slack / 群聊</td><td>专属共享虚拟机</td></tr></tbody></table><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>名称与岗位描述清晰。</li><li>所有者机密隔离完好。</li><li>3 字符检索或链接可唤起。</li><li>跨人调用触发 Allow 授权，无越权隐患。</li></ul><h2 id="_1-n-主-bot-派活模式-单入口与履约章程" tabindex="-1">1+N 主 Bot 派活模式：单入口与履约章程 <a class="header-anchor" href="#_1-n-主-bot-派活模式-单入口与履约章程" aria-label="Permalink to &quot;1+N 主 Bot 派活模式：单入口与履约章程&quot;">​</a></h2><p><img src="'+r+`" alt="1+N 主 Bot 派活模式：单入口与履约章程" width="1600" height="1013" loading="lazy" decoding="async"></p><p>别让所有 Bot 都对接用户，免得你在窗口间传话，群聊也白耗 Token。</p><p><strong>推荐采用 1+N 模式，你只跟统筹主 Bot 沟通</strong>，由它拆解、派活与汇总，详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/DdqFwLmn7i8cV1kYtDwc840enLg" target="_blank" rel="noreferrer">《从一个 Bot 到一整个组织，Grok Bot 的进阶用法分享：本地电脑、AI 分工和知识库怎么接起来》</a>。</p><h3 id="主-bot-六行章程与专职边界" tabindex="-1">主 Bot 六行章程与专职边界 <a class="header-anchor" href="#主-bot-六行章程与专职边界" aria-label="Permalink to &quot;主 Bot 六行章程与专职边界&quot;">​</a></h3><p><strong>主 Bot 只负责路由与监督，绝不能亲自写长代码或长文。</strong> 在 Profile Description 写入六行章程，使其无事静默、有事派活，超长汇报存为文件。</p><p>团队组织规范参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Own: 负责需求的统一拆解、分派、汇总与五行简报汇报。</span></span>
<span class="line"><span>Sources: 人工下发的指令、项目看板文件。</span></span>
<span class="line"><span>Output: 纯文本状态摘要，超出五行时输出为指定文件路径。</span></span>
<span class="line"><span>Approval: 任何对外通信、采购、删除操作必须暂停等待确认。</span></span>
<span class="line"><span>Failure: 下游专职 Bot 报错时如实上报，不使用过期数据假装完成。</span></span>
<span class="line"><span>Never: 永远不直接编写业务代码，不擅自修改生产配置。</span></span></code></pre></div><p>专职 Bot 须在 Description 写死负向边界：</p><ul><li>广告投手 Bot：分析数据并出具待批清单，<strong>绝不碰后台与出价，不调预算，也不加词或建组</strong>。</li><li>文案创作 Bot：只出草稿文件，严禁调接口直接上线公开内容。</li><li>竞品调研 Bot：前台只看不动，严禁下单加购，也不留评或向卖家提问，防反爬封禁。</li></ul><p>投放专员直接套用提示词模板。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Own: 负责广告投放数据诊断与策略输出。</span></span>
<span class="line"><span>Sources: 运营分析文件 /workspace/project/ad_data.json。</span></span>
<span class="line"><span>Output: 待批操作清单 /workspace/project/pending_actions.md，列出出价建议与预期影响。</span></span>
<span class="line"><span>Approval: 绝不直接写入广告后台，不修改出价，不修改预算，不加否定词，所有操作必须等待人工审批。</span></span>
<span class="line"><span>Failure: 数据缺失时明确标注缺失字段，不推测填充。</span></span>
<span class="line"><span>Never: 绝不执行任何后台写入与线上提交操作。</span></span></code></pre></div><h3 id="待批清单与验收" tabindex="-1">待批清单与验收 <a class="header-anchor" href="#待批清单与验收" aria-label="Permalink to &quot;待批清单与验收&quot;">​</a></h3><p><strong>专职 Bot 只输出结构化待批清单，把决定权留给人工。</strong> 比如主 Bot 汇总出 5 条广告出价冲突项，你回复“确认建议”或批注修改后才触发下一步。</p><p>系统达标后按三项标准验收：</p><table tabindex="0"><thead><tr><th>验收项</th><th>达标标准</th></tr></thead><tbody><tr><td>交互与主 Bot</td><td>单入口清晰运行；主 Bot 不写长代码、不写长文章</td></tr><tr><td>专职 Bot</td><td>各司其职，只产出结构化清单</td></tr><tr><td>高风险动作</td><td>不可逆操作均有明确人工确认卡点</td></tr></tbody></table><h2 id="交接文件约定-以共享文件系统替代对话历史" tabindex="-1">交接文件约定：以共享文件系统替代对话历史 <a class="header-anchor" href="#交接文件约定-以共享文件系统替代对话历史" aria-label="Permalink to &quot;交接文件约定：以共享文件系统替代对话历史&quot;">​</a></h2><p><img src="`+i+`" alt="交接文件约定：以共享文件系统替代对话历史" width="1600" height="1013" loading="lazy" decoding="async"></p><p>别让 Bot A 在聊天窗贴结果再给 Bot B 读。<strong>窗口交互会快速撑爆上下文且容易丢失历史</strong>，各 Bot 对话在底层逻辑隔离，根本没法互相检索。</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">特征与包含内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>物理共享层</strong></td><td style="text-align:left;">同账号下所有 Bot 共用虚拟机、<code>/workspace</code> 目录、连接器与公共 Skill 库。</td></tr><tr><td style="text-align:left;"><strong>逻辑隔离层</strong></td><td style="text-align:left;">对话历史互不可见，Bot A 无法调取 Bot B 与用户的私人对话。</td></tr></tbody></table><p>物理磁盘既然共享，传递任务就靠本地结构化文件，对话框只用来同步状态与路径。</p><h3 id="文件交接流水线标准" tabindex="-1">文件交接流水线标准 <a class="header-anchor" href="#文件交接流水线标准" aria-label="Permalink to &quot;文件交接流水线标准&quot;">​</a></h3><p>标准交接包含落盘、传路径，再到读取与归档。</p><details class="details custom-block"><summary>文件交接流水线标准</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[用户指令] ──&gt; (主调度 Bot)</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>         1. 派发任务 (指定输出路径)</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>             [专职 Bot A] ──&gt; 写入 /workspace/proj/data.json</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>         2. 交付：仅返回文件绝对路径</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>             (主调度 Bot)</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>         3. 调度下发 (附带输入路径)</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>             [专职 Bot B] ──&gt; 读取 data.json ──&gt; 写入 output.md</span></span>
<span class="line"><span>                   │</span></span>
<span class="line"><span>         4. 汇总简报至用户</span></span></code></pre></div></details><ol><li><strong>任务派发</strong>：主 Bot 明确指定交付绝对路径，如 <code>/workspace/project-alpha/data.json</code>。</li><li><strong>数据落盘</strong>：专职 Bot A 跑完清洗写入文件，在对话框只回一句话通知保存路径。</li><li><strong>路径传递与读取</strong>：主 Bot 唤醒 Bot B 并传递路径，Bot B 读盘分析后把结论写入 <code>/workspace/project-alpha/report.md</code>。</li><li><strong>交付呈现</strong>：主 Bot 提炼摘要，附上本地或云文档链接供审查。</li></ol><p>推文画像流水线也是这套模式，整理员抓取存入 <code>tweets.md</code>，分析师读文件提炼标签写入 <code>profile.md</code>，设计师输出 <code>design.md</code>，工程师据此写代码并给预览截图。</p><p>实操参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a>。</p><h3 id="接入飞书云文档实现可追溯交付" tabindex="-1">接入飞书云文档实现可追溯交付 <a class="header-anchor" href="#接入飞书云文档实现可追溯交付" aria-label="Permalink to &quot;接入飞书云文档实现可追溯交付&quot;">​</a></h3><p>需要团队协作或批注时，给虚拟机配飞书 CLI 把 Markdown 发为云文档。它自带独立链接方便分发，支持逐段批注，也能<strong>保障企业数据安全</strong>。</p><p>工作流达标包含这几项要求：</p><ul><li>链路中每个 Bot 都能独立读写 <code>/workspace</code> 下的固定文件。</li><li><strong>对话框只传输状态提示与文件绝对路径</strong>。</li><li>出现异常时，检查对应磁盘文件即可复现定位。</li></ul><h2 id="用量影响与额度控制-the-x-subscription-下的多-bot-治理" tabindex="-1">用量影响与额度控制：The X Subscription 下的多 Bot 治理 <a class="header-anchor" href="#用量影响与额度控制-the-x-subscription-下的多-bot-治理" aria-label="Permalink to &quot;用量影响与额度控制：The X Subscription 下的多 Bot 治理&quot;">​</a></h2><p>2026-10-12 起 Grok Bot 纳入 The X Subscription，<strong>统一按周共享额度</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">档位</th><th style="text-align:left;">价格</th></tr></thead><tbody><tr><td style="text-align:left;">Premium</td><td style="text-align:left;">$30/月</td></tr><tr><td style="text-align:left;">Super</td><td style="text-align:left;">$100/月</td></tr><tr><td style="text-align:left;">Ultra</td><td style="text-align:left;">$200/月</td></tr></tbody></table><h3 id="规则与防烧策略" tabindex="-1">规则与防烧策略 <a class="header-anchor" href="#规则与防烧策略" aria-label="Permalink to &quot;规则与防烧策略&quot;">​</a></h3><ol><li><strong>回复与握手消息都计费</strong>。私聊团队 Bot 扣自己额度，群聊扣发起方的，周初耗尽整周停摆。</li><li>群聊 Bot 压在 3 个以内，<strong>坚决用 1+N 串行替代自由群聊</strong>。</li><li>清洗等轻任务用基础模型，核心推导才用顶级推理模型。</li><li>没跑稳前<strong>别设半小时或每小时的定时例程</strong>，防夜间重试上百次耗尽额度。</li></ol><h3 id="验收标准-2" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-2" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li><strong>周额度平稳消耗</strong>，没有夜间死循环。</li><li>模型分层分明，费用分摊到具体提问者。</li></ul><h2 id="实战案例-企业专家经验固化与跨境团队-1-n-落地" tabindex="-1">实战案例：企业专家经验固化与跨境团队 1+N 落地 <a class="header-anchor" href="#实战案例-企业专家经验固化与跨境团队-1-n-落地" aria-label="Permalink to &quot;实战案例：企业专家经验固化与跨境团队 1+N 落地&quot;">​</a></h2><h3 id="spacexai-团队-bot" tabindex="-1">SpaceXAI 团队 Bot <a class="header-anchor" href="#spacexai-团队-bot" aria-label="Permalink to &quot;SpaceXAI 团队 Bot&quot;">​</a></h3><p>n2parko 团队<strong>让业务专家亲自配 Bot 规则</strong>，做成全员共享助手。</p><ol><li>抓高频节点：数据团队做 Databot 查数据湖，避免重复打扰专家。</li><li>扩充岗位：配置 10x Engineer、Marketing 及查 Salesforce 的 Sales Assistant（辅助 SDR/AE）。</li><li>记忆分层：全局沉淀通用规则且保留个人偏好，详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KS9Cwan52idy1xkLbnTcSC3xnxb" target="_blank" rel="noreferrer">《Meet your Team Bots｜n2parko》</a>。</li></ol><h3 id="跨境-1-12-编排" tabindex="-1">跨境 1+12 编排 <a class="header-anchor" href="#跨境-1-12-编排" aria-label="Permalink to &quot;跨境 1+12 编排&quot;">​</a></h3><p>Zach（@1999Zach22）以 1 船长带 12 岗位，<strong>自动化闭环必须设待批清单</strong>，严控写权限。</p><ol><li>本地部署：专用 Skill 在本地调顺后，统一部署到云电脑。</li><li>负向边界：投手严禁操作后台仅提建议；调研买家号严禁加购、提问和留评。</li><li>单入口交互：每天汇总简报，遇冲突出 5 处冲突待批单，确认后执行。</li><li>报表沉淀：用飞书 CLI 把报表落成云文档持久链接，详见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/DdqFwLmn7i8cV1kYtDwc840enLg" target="_blank" rel="noreferrer">《从一个 Bot 到一整个组织，Grok Bot 的进阶用法分享：本地电脑、AI 分工和知识库怎么接起来》</a>。</li></ol><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li>用三个词界定不了独特技能的，<strong>收拢为主 Bot 的 Skill</strong>。别一口气建七八个职能模糊的助手，免得整天在窗口间切换。</li><li>同账号所有 Bot 共享云电脑虚拟机、本地路径和浏览器登录态，<strong>共享 Bot 切勿存个人私有凭证</strong>。</li><li>群指令别太宽泛。Bot 互相客套确认会狂扣额度，<strong>可能半天耗完一周调用量</strong>。</li><li>别留着 <code>New team bot</code> 默认名且不写描述就发布，<strong>其他成员在搜索列表完全看不到它</strong>。</li><li>团队 Bot 和本地 Bot 进不了同个群，群里也没语音入口。<strong>有这类需求必须切到单 Bot 私聊</strong>。</li><li>写上千行代码会填满上下文并失去全局视野。<strong>主 Bot 必须只负责调度与督办</strong>，落地动作交由专职 Bot 执行。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li><strong>主 Bot 路由</strong>：发跨模块业务指令，主 Bot 须<strong>准确复述目标并列出专职 Bot 路径</strong>，无外部状态变化时保持静默。</li><li><strong>群聊防互发</strong>：下令要求“不要给其他 Bot 发消息”，<strong>Bot 只在群内回复</strong>，绝不私聊窗口弹消息，也不私下互唤。</li><li><strong>检索与授权</strong>：换成员 Cursor 账号在 <strong>New chat</strong> &gt; <strong>团队 Bot</strong> 搜<strong>前 3 个字符</strong>；调插件必弹出含 <strong>Allow once</strong>、<strong>Always allow</strong> 与 <strong>Skip</strong> 的授权卡片。</li><li><strong>文件交接</strong>：A 将中间文件存入 <code>/workspace</code>，<strong>Bot B 只凭绝对路径独立跑完</strong>，全程无需人工复制。</li><li><strong>人闸拦截</strong>：下达发布、后台修改或删除指令，<strong>Bot 必须中止执行并输出待批清单</strong>，未经人工审批绝不线上写入。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h3><ul><li><a href="/part3/22-feishu-wechat">第 22 章 接入飞书与微信</a></li><li><a href="/part4/24-roles">第 24 章 按岗位组建你的 AI 团队</a></li></ul><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/help/grok-bot/group-chats" target="_blank" rel="noreferrer">群组聊天与机器人间消息</a></li><li><a href="https://cursor.com/cn/help/grok-bot/team-bots" target="_blank" rel="noreferrer">团队 Bot</a></li></ul><h3 id="社区实战来源" tabindex="-1">社区实战来源 <a class="header-anchor" href="#社区实战来源" aria-label="Permalink to &quot;社区实战来源&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/KS9Cwan52idy1xkLbnTcSC3xnxb" target="_blank" rel="noreferrer">《Meet your Team Bots｜n2parko》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/DdqFwLmn7i8cV1kYtDwc840enLg" target="_blank" rel="noreferrer">《从一个 Bot 到一整个组织，Grok Bot 的进阶用法分享：本地电脑、AI 分工和知识库怎么接起来》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/POTrwwThoiQxIakFDIDcUcKjnmh" target="_blank" rel="noreferrer">《4.2 团队编排：章程、岗位与放权》</a></li></ul>`,98)])])}const m=a(p,[["render",d]]);export{k as __pageData,m as default};
